with open('tests/concurrency/context.py', 'rb') as f:
    content = f.read()

# Fix ConcurrentTestRunner to use the passed harness instead of creating SimpleHarness
old = b'    def __init__(\r\n        self,\r\n        session_factory,\r\n        actors: List[\'CanonicalActor\'],\r\n        barrier: Optional[\'ConcurrencyBarrier\'] = None,\r\n    ):\r\n        self.session_factory = session_factory\r\n        self.actors = {a.user_id: a for a in actors}\r\n        self.results: List[ConcurrentTestResult] = []\r\n        self._results_lock = asyncio.Lock()\r\n        self.barrier = barrier\r\n        # Create a simple harness-like object with session_for method\r\n        class SimpleHarness:\r\n            def __init__(self, session_factory):\r\n                self.session_factory = session_factory\r\n            \r\n            @asynccontextmanager\r\n            async def session_for(self, actor_id: str):\r\n                async with self.session_factory() as session:\r\n                    print(f"DEBUG SimpleHarness: session_for {actor_id} start", flush=True)\r\n                    try:\r\n                        yield SessionContext(session=session, actor=None)\r\n                    finally:\r\n                        print(f"DEBUG SimpleHarness: session_for {actor_id} end", flush=True)\r\n        \r\n        self.harness = SimpleHarness(session_factory)'
new = b'    def __init__(\r\n        self,\r\n        session_factory,\r\n        actors: List[\'CanonicalActor\'],\r\n        barrier: Optional[\'ConcurrencyBarrier\'] = None,\r\n        harness=None,\r\n    ):\r\n        self.session_factory = session_factory\r\n        self.actors = {a.user_id: a for a in actors}\r\n        self.results: List[ConcurrentTestResult] = []\r\n        self._results_lock = asyncio.Lock()\r\n        self.barrier = barrier\r\n        # Use provided harness or create a default one with transaction support\r\n        if harness is not None:\r\n            self.harness = harness\r\n        else:\r\n            class SimpleHarness:\r\n                def __init__(self, session_factory):\r\n                    self.session_factory = session_factory\r\n                \r\n                @asynccontextmanager\r\n                async def session_for(self, actor_id: str):\r\n                    async with self.session_factory() as session:\r\n                        async with session.begin():\r\n                            yield SessionContext(session=session, actor=None)\r            \r\n            self.harness = SimpleHarness(session_factory)'

content = content.replace(old, new)

with open('tests/concurrency/context.py', 'wb') as f:
    f.write(content)
print('Fixed ConcurrentTestRunner to use passed harness')